// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

/**
 * The deterministic work budget must not latch: one refused optional block marks the search incomplete but leaves the
 * remaining units available to smaller optional blocks and to mandatory completions.
 */
class PackedSearchBudgetTest {

	@Test
	void oneOversizedOptionalReservationMustNotExhaustTheRemainingBudget() {
		PackedSearchBudget budget = new PackedSearchBudget(1_000L, Long.MAX_VALUE);
		assertTrue(budget.tryReserve(10L));
		assertFalse(budget.tryReserve(5_000L), "an oversized optional block is refused");
		assertTrue(budget.tryReserve(1L),
				"990 units remain but the budget latched workLimitReached after one refused optional block: used="
						+ budget.workUnits() + " workLimitReached=" + budget.workLimitReached());
		assertTrue(budget.canReserveMandatoryCompletion(1L),
				"a mandatory completion that fits must be admitted after a refused optional block");
	}

	@Test
	void refusedOptionalBlockChargesNothingAndTheRemainderIsAdmittedExactlyOnce() {
		PackedSearchBudget budget = new PackedSearchBudget(1_000L, Long.MAX_VALUE);
		assertTrue(budget.tryReserve(10L));
		assertFalse(budget.tryReserve(5_000L));
		assertEquals(10L, budget.workUnits(), "a refused block must charge nothing");
		assertEquals(990L, budget.remainingWorkUnits(), "the remainder stays available after a refusal");
		assertTrue(budget.tryReserve(990L), "a block equal to the remainder fits exactly once");
		assertEquals(1_000L, budget.workUnits());
		assertEquals(0L, budget.remainingWorkUnits());
		assertFalse(budget.tryReserve(1L), "nothing is admitted once the limit is genuinely reached");
		assertFalse(budget.canConsume(1L));
		assertTrue(budget.workLimitReached());
	}

	@Test
	void refusedOptionalBlockReportsAnIncompleteSearchButAdmitsMandatoryCompletion() {
		PackedSearchBudget budget = new PackedSearchBudget(1_000L, Long.MAX_VALUE);
		assertTrue(budget.tryReserve(10L));
		assertFalse(budget.tryReserve(5_000L));

		assertTrue(budget.workLimitReached(), "a refused block means the search is incomplete");
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT, budget.completionStatus());
		assertEquals(990L, budget.remainingWorkUnits());
		assertTrue(budget.canConsume(1L), "one more unit of optional work still fits");
		assertTrue(budget.sampleDeadline(), "a refused deterministic block is not a deadline");
		assertTrue(budget.canBeginMandatoryCompletion(1L),
				"the mandatory-completion phase gate must stay open while work remains");
		assertTrue(budget.canReserveMandatoryCompletion(1L));
		assertTrue(budget.tryReserveMandatoryCompletion(1L),
				"a mandatory completion that fits must be charged after a refused optional block");
		assertEquals(11L, budget.workUnits());
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT, budget.completionStatus(),
				"admitting more work never turns an incomplete search back into a complete one");
	}

	@Test
	void oversizedMandatoryCompletionIsRefusedWithoutChargingAndSmallerCompletionStillFits() {
		PackedSearchBudget budget = new PackedSearchBudget(100L, Long.MAX_VALUE);
		assertTrue(budget.tryReserve(40L));
		assertFalse(budget.canReserveMandatoryCompletion(61L));
		assertFalse(budget.tryReserveMandatoryCompletion(61L));
		assertEquals(40L, budget.workUnits());
		assertTrue(budget.workLimitReached());
		assertTrue(budget.tryReserveMandatoryCompletion(60L));
		assertEquals(100L, budget.workUnits());
		assertFalse(budget.tryReserveMandatoryCompletion(1L));
	}

	@Test
	void deadlineStopsOptionalWorkButNotMandatoryCompletion() {
		PackedSearchBudget budget = new PackedSearchBudget(1_000L, System.nanoTime() - 1L);
		assertFalse(budget.tryReserve(1L), "optional work is refused once the deadline has passed");
		assertTrue(budget.deadlineReached());
		assertFalse(budget.workLimitReached());
		assertFalse(budget.sampleDeadline());
		assertFalse(budget.canConsume(1L));
		assertEquals(0L, budget.remainingWorkUnits());
		assertTrue(budget.tryReserveMandatoryCompletion(1L),
				"the deterministic work limit remains authoritative for mandatory completions");
		assertEquals(1L, budget.workUnits());
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, budget.completionStatus());
	}

	@Test
	void refusedOptionalBlockFollowedByTheDeadlineReportsOneCompletionStatus() {
		PackedSearchBudget budget = new PackedSearchBudget(1_000L, System.nanoTime() - 1L);
		// the arithmetic gate refuses before the deadline is sampled
		assertFalse(budget.tryReserve(5_000L));
		assertTrue(budget.workLimitReached());
		assertFalse(budget.deadlineReached());
		// the deadline is discovered by the next optional block
		assertFalse(budget.tryReserve(1L));
		assertTrue(budget.deadlineReached());
		assertTrue(budget.workLimitReached());

		PackedSearchCompletionStatus status = budget.completionStatus();
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT, status,
				"the deterministic limit ranks above the wall-clock deadline");
		StatementPattern plan = new StatementPattern(Var.of("s"),
				Var.of("p", SimpleValueFactory.getInstance().createIRI("urn:p")), Var.of("o"));
		assertDoesNotThrow(() -> new PackedPlanningResult(plan, 1.0d, 1.0d, null,
				status == PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT,
				status == PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, 0L, status, 0L),
				"legacy flags derived from the completion status always agree with it");
	}

	@Test
	void resourceLimitStillClosesEveryGate() {
		PackedSearchBudget budget = new PackedSearchBudget(1_000L, Long.MAX_VALUE);
		assertTrue(budget.tryReserve(10L));
		budget.markResourceLimitReached();
		assertFalse(budget.tryReserve(1L));
		assertFalse(budget.tryReserveMandatoryCompletion(1L));
		assertFalse(budget.canReserveMandatoryCompletion(1L));
		assertFalse(budget.canBeginMandatoryCompletion(1L));
		assertFalse(budget.canConsume(1L));
		assertFalse(budget.sampleDeadline());
		assertEquals(0L, budget.remainingWorkUnits());
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_RESOURCE_LIMIT, budget.completionStatus());
	}
}
